/** Rephrased from the user-supplied ccar-f.pptx. Screenshot selections are
 * not an answer key. 57 readable unique items; Q13/18/47 are unavailable.
 * Original numbers/slides are provenance only, never exam sequence numbers.
 * Every question carries its scenario in the stem for web/mobile/PDF parity.
 */
import { type CleanQuestion, validateQuestion } from '../question-input';

export const CCAR_PPTX_TAG = 'manual:ccar-f-pptx-2026-11-13';
export const CCAR_SCENARIOS = {
  extraction: {
    title: 'Structured document extraction',
    text: 'You are developing a Claude document extraction service. It converts unstructured source material into JSON, validates records against JSON schemas, and passes them to downstream systems. The service must preserve source accuracy, handle missing or ambiguous information, and support review of difficult cases.'
  },
  coding: {
    title: 'Claude Code development workflow',
    text: 'Your engineering team uses Claude Code to generate and refactor code, investigate defects, and write documentation. You are configuring project instructions, reusable commands, skills, and integrations, and choosing an effective planning and iteration workflow for each development task.'
  },
  developer: {
    title: 'Developer productivity agent',
    text: 'You are building an engineering assistant with the Claude Agent SDK. It explores unfamiliar repositories, explains legacy systems, generates boilerplate, and automates routine development work. It can use Read, Write, Bash, Grep, and Glob, alongside tools exposed by Model Context Protocol (MCP) servers.'
  },
  support: {
    title: 'Customer support resolution agent',
    text: 'You are implementing a Claude Agent SDK support assistant for returns, billing disputes, and account problems. Backend MCP tools include get_customer, lookup_order, process_refund, and escalate_to_human. The service aims to resolve more than 80% of cases at first contact while handing off cases that require human authority or assistance.'
  }
} as const;

const DOMAINS = {
  architecture: 'Agentic Architecture & Orchestration',
  tools: 'Tool Design & MCP Integration',
  coding: 'Claude Code Configuration & Workflows',
  prompting: 'Prompt Engineering & Structured Output',
  context: 'Context Management & Reliability'
} as const;
const REFS = {
  tools: 'https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools',
  results: 'https://platform.claude.com/docs/en/agents-and-tools/tool-use/handle-tool-calls',
  structured: 'https://platform.claude.com/docs/en/build-with-claude/structured-outputs',
  hallucinations: 'https://platform.claude.com/docs/en/test-and-evaluate/strengthen-guardrails/reduce-hallucinations',
  examples: 'https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/multishot-prompting',
  evals: 'https://platform.claude.com/docs/en/test-and-evaluate/develop-tests',
  workflows: 'https://code.claude.com/docs/en/best-practices',
  memory: 'https://code.claude.com/docs/en/memory',
  mcp: 'https://code.claude.com/docs/en/mcp',
  hooks: 'https://code.claude.com/docs/en/hooks',
  permissions: 'https://code.claude.com/docs/en/permissions',
  skills: 'https://code.claude.com/docs/en/skills',
  sessions: 'https://code.claude.com/docs/en/agent-sdk/sessions',
  subagents: 'https://code.claude.com/docs/en/agent-sdk/subagents',
  patterns: 'https://www.anthropic.com/research/building-effective-agents',
  cli: 'https://code.claude.com/docs/en/cli-reference'
} as const;
export type CcarPptxQuestion = CleanQuestion & { sourceNumber: number; sourceSlides: number[]; scenarioId: keyof typeof CCAR_SCENARIOS };
export const CCAR_PPTX_QUESTIONS: CcarPptxQuestion[] = [];
function add(n: number, slides: number[], scenarioId: keyof typeof CCAR_SCENARIOS, domain: keyof typeof DOMAINS,
  question: string, choices: [string, string, string, string], key: string, explanation: string, refs: (keyof typeof REFS)[]) {
  const scenario = CCAR_SCENARIOS[scenarioId];
  const result = validateQuestion({
    type: 'SINGLE', domain: DOMAINS[domain], difficulty: 3,
    stem: `Scenario: ${scenario.title}\n${scenario.text}\n\nQuestion:\n${question}`,
    options: choices.map((text, i) => ({ id: 'abcd'[i], text })), correct: [key], explanation,
    references: refs.map(r => `Claude documentation: ${r} | ${REFS[r]}`).join('\n')
  });
  if (!result.ok) throw new Error(`CCAR-F source Q${n}: ${result.error}`);
  CCAR_PPTX_QUESTIONS.push({ ...result.value, sourceNumber: n, sourceSlides: slides, scenarioId });
}

add(1, [59], 'extraction', 'prompting',
  'Your pipeline retries invalid extractions with the validator error included in the next request. Which problem is least likely to be solved by repeating this process without adding new source information?',
  ['Dates are returned with a time component although the schema expects YYYY-MM-DD.', 'The output abbreviates an author list because the complete names exist only in another document that was never supplied.', 'Keywords are grouped in an object although the schema requires a flat string array.', 'Citation totals contain thousands separators although the schema requires integers.'], 'b',
  'The missing author list is unavailable evidence. Error feedback can help repair a date format, array shape, or integer representation, but cannot recover facts from a document the model has not received. Retrieve the missing source or represent the information as unknown; further retries must not manufacture names.', ['hallucinations', 'structured']);
add(2, [49, 60], 'extraction', 'prompting',
  'When a product document lists dimensions but no weight, Claude invents a plausible weight to fill a required field. Which schema change most directly removes the pressure to fabricate missing specifications?',
  ['Make specifications optional when they may be absent, so those properties can be omitted.', 'Require a self-reported confidence score for every specification and discard low scores.', 'Check each result against the document after extraction without changing the schema.', 'Keep every field mandatory and ask for placeholder text whenever the source is silent.'], 'a',
  'Allowing absent specifications to be omitted gives the model a valid representation of missing evidence. A nullable field with an explicit null policy is another suitable design when fixed keys are required. Confidence scores do not establish truth, and post-validation alone does not fix a schema that demands unsupported facts. Placeholder text can also violate numeric types.', ['structured', 'hallucinations']);
add(3, [61], 'extraction', 'context',
  'Reviewers can inspect only about 5% of extraction records. Which selection policy best directs this limited capacity toward likely mistakes?',
  ['Wait for downstream consumers to report errors before reviewing a record.', 'Review every record containing a financial figure or date without considering uncertainty.', 'Prioritize records with low extraction confidence or ambiguous or conflicting source evidence.', 'Select all review candidates using an entirely random 5% sample.'], 'c',
  'Targeting uncertainty and conflicting evidence concentrates reviewer effort on difficult records. Confidence should be calibrated against reviewed outcomes and combined with observable ambiguity; a model score is not a guarantee. A small random audit is useful for discovering blind spots, but random-only selection is less effective for the immediate task of prioritizing a constrained review queue.', ['evals', 'hallucinations']);
add(4, [62], 'extraction', 'prompting',
  'For 18% of invoice extractions, the line items and applicable taxes do not reconcile with the extracted grand total. Both OCR defects and extraction mistakes occur, and accounting rejects inconsistent records. Which approach best preserves reliable data?',
  ['Ask a second model to guess which conflicting amounts should replace the original values.', 'Add examples with matching arithmetic and assume future invoices will reconcile.', 'Retain separate calculated and source-stated totals, and send discrepancies for human review.', 'Scale the line-item values proportionally until their sum equals the printed total.'], 'c',
  'Keeping the calculated total separate from the stated total exposes disagreement without altering evidence. Recompute arithmetic deterministically in application code, accounting for tax, discounts, and rounding, then review discrepancies against the source. Another model or examples cannot guarantee the right numbers, while proportional adjustments silently invent accounting data.', ['structured', 'evals']);
add(5, [63], 'extraction', 'prompting',
  'About 12% of records fail Pydantic checks, for example when quantity must be numeric but the output is "2 to 3". Sending the identical request again repeats the same failure. What should the recovery request include?',
  ['The rejected output and precise validation error, with a request to correct it using the source and permitted ambiguity rules.', 'Only a switch to a larger model, leaving the original request unchanged.', 'A requirement to rewrite every source document before attempting another extraction.', 'Only a temperature setting of zero.'], 'a',
  'Specific validation feedback tells the model which field and constraint failed, enabling a targeted correction rather than an unchanged retry. A range must not be arbitrarily converted to one number: if the source is ambiguous and the schema cannot represent it, use the approved null/review path or revise the schema. Model size and temperature do not resolve a missing representation policy.', ['structured', 'hallucinations']);
add(6, [64], 'extraction', 'prompting',
  'Reviewers corrected 847 recipe extractions in three weeks. Informal amounts such as "a handful" and "a splash" account for 23% of corrections because the model invents numeric equivalents or omits them. How should this feedback inform the prompt?',
  ['Immediately fine-tune on the complete correction set.', 'Add examples showing that informal amounts should be preserved verbatim instead of converted or dropped.', 'Fill empty results with a pattern-matching fallback without teaching the extraction behavior.', 'Add a precise/informal measurement category but leave the extraction instructions unchanged.'], 'b',
  'Examples drawn from the recurring error pattern teach the intended treatment: retain the source phrase without inventing precision. The schema must also permit that representation. An enum alone does not teach how to populate the amount, and a fallback only treats some symptoms. First measure the prompt change against held-out examples before considering more complex training.', ['examples', 'evals']);
add(7, [65], 'extraction', 'prompting',
  'A resume service must return names, contact information, skills, work history, and education in a fixed JSON schema. Which mechanism most reliably enforces the output structure for a successfully completed response?',
  ['Configure JSON structured outputs with the schema in output_config.format.', 'Put a JSON template in the system prompt and request JSON only.', 'Extract a JSON-looking substring with regular expressions and retry parse failures.', 'Extract prose first and then ask another model call to convert it to JSON.'], 'a',
  'JSON structured outputs constrain supported schema structure through output_config.format. Prompt-only templates, regex recovery, and a second formatting call do not provide the same structural enforcement. Schema compliance does not prove factual accuracy; still check source support and handle refusals or token-limit truncation before consuming a response.', ['structured']);
add(8, [50, 66], 'extraction', 'prompting',
  'A skills string array is inconsistent: "Python and SQL" may become one entry or two, inferred skills appear, and similar resumes yield anywhere from a few entries to more than forty. The instruction only says to extract mentioned skills. What best clarifies the desired behavior?',
  ['Normalize names against a taxonomy only after extraction.', 'Impose an arbitrary 10–20 item limit and prohibit inferred skills.', 'Add confidence and quotation properties without specifying extraction examples.', 'Provide examples that show how to split compound phrases, require explicit mentions, and maintain a consistent level of detail.'], 'd',
  'Representative examples jointly define compound handling, evidence requirements, and entry granularity, addressing all three observed ambiguities. A fixed count can discard valid skills or encourage padding; taxonomy mapping cannot recover incorrectly omitted or inferred facts. Metadata is useful for auditing but does not itself define the desired extraction behavior.', ['examples']);
add(9, [1, 67], 'extraction', 'tools',
  'Each submitted document must invoke extract_fields before normal assistance continues. Other tools, lookup_vendor and flag_for_review, support follow-up requests. Claude sometimes performs only the vendor lookup. Using a model configuration that supports forced tool choice, how should the pipeline require the extraction call while retaining flexible follow-up behavior?',
  ['Use auto selection and put extract_fields first in the tool list.', 'Force the named extract_fields tool on the initial submission request, then restore auto selection on subsequent turns.', 'Force extract_fields on every request, including all follow-up turns.', 'Require any tool and rely on prompt wording to make extraction the preferred choice.'], 'b',
  'A named tool_choice selection requires that specific tool on the extraction step; returning to auto afterward permits vendor lookup, review, and a final response. Tool ordering and any-tool selection do not ensure extract_fields is chosen. Forcing extraction forever can prevent completion. The application must still execute and verify the tool result, handle API failures, and use a compatible model/thinking configuration.', ['tools']);
add(10, [2, 51], 'extraction', 'prompting',
  'Restaurant menus express prices as either "$12" or "12.00" and dietary properties as words or icons. What best establishes a consistent JSON contract for item names, descriptions, prices, and dietary labels?',
  ['Accept arbitrary extracted representations and rely entirely on downstream cleanup.', 'Use a separate model call for every individual field.', 'Specify a strict output schema and explicit normalization rules for price and dietary representations.', 'Generate several outputs and choose whichever formatting occurs most often.'], 'c',
  'The schema defines the structure and types, while explicit normalization rules define how different source representations map into those fields. Validate the final record and use deterministic code for arithmetic or canonical cleanup where appropriate. Separate calls and majority-format selection add cost without establishing a single contract; unconstrained output shifts ambiguity downstream.', ['structured', 'examples']);
add(11, [3], 'extraction', 'prompting',
  'Contracts often contain amendments: the original payment term may be 30 days while a later amendment changes it to 45 days. The extractor inconsistently returns either value without explaining which governs. Which design best preserves the evidence needed to resolve the effective term?',
  ['Detect amendment phrases with post-extraction pattern matching and review every match.', 'Remove text classified as superseded before the primary extraction.', 'Represent original and amended values separately, each with a source location and effective date.', 'Tell the model to return only the newest value and discard the original.'], 'c',
  'Recording each version, its location, and effective date preserves the amendment relationship and supports an auditable determination of the governing value. Removing earlier clauses or returning one value destroys evidence that may be needed to interpret scope or timing. Review flags can help, but do not fix a schema that collapses multiple legally distinct values into one.', ['structured', 'hallucinations']);
add(12, [52], 'extraction', 'context',
  'Records with confidence below 85% already go to review, but an audit finds errors in 12% of the higher-confidence records. Causes include competitor comparison tables, variant-specific appendices, and ambiguous wording. Which ongoing approach best detects unknown error patterns and measures improvement?',
  ['Re-extract every high-confidence record and review only disagreements between the two runs.', 'Review a stratified random sample of high-confidence records weekly and track error rates over time.', 'Reduce the review cutoff from 85% to 70% to increase the reviewed volume.', 'Flag only documents containing the currently known comparison-table or appendix patterns.'], 'b',
  'Stratified sampling across relevant document groups provides observations from the high-confidence population, reveals new failure patterns, and supports comparable error-rate estimates over time. Repeated model runs can agree on the same mistake. Reviewing below 70% instead of below 85% would shrink the existing queue, and heuristics tied only to known layouts miss novel errors.', ['evals']);
add(14, [4, 53], 'extraction', 'prompting',
  'All fields in your event schema permit null, yet Claude supplies an invented attendee_count when a news article says nothing about attendance. Which change most directly uses the schema to prevent this behavior?',
  ['Make every field non-nullable and mandatory.', 'Explicitly instruct Claude to return null when the source does not state a field value.', 'Change only to a more capable model.', 'Always add a second model call before correcting the extraction instructions.'], 'b',
  'The schema already provides a missing-value representation, but the prompt must say when to use it. Requiring direct source evidence and null for absent information reduces pressure to guess. Making the field non-nullable makes that pressure worse. Additional verification may help, but correcting the missing evidence rule is the most direct intervention.', ['hallucinations', 'structured']);
add(15, [54], 'extraction', 'context',
  'After three months of complete human review, records with confidence of at least 90% appear 97% accurate overall. Before automatically accepting these records, what validation most directly checks whether the aggregate result hides weak segments?',
  ['Release a two-week pilot immediately and wait for downstream error reports.', 'Measure accuracy separately by document category and extracted field within the high-confidence group.', 'Compare only the overall accuracy at several confidence thresholds.', 'Ask downstream teams whether the aggregate 97% figure is acceptable without inspecting subgroups.'], 'b',
  'Segment-level evaluation reveals whether apparently strong overall results conceal poor accuracy for a particular field or document type. A single automation threshold may be unsuitable for those groups. Overall threshold comparisons and acceptance discussions are useful later, but cannot establish that every segment is safe to automate.', ['evals']);

add(16, [5], 'coding', 'coding',
  'The application needs live updates. WebSockets, server-sent events, and polling differ in infrastructure needs, browser behavior, and complexity. How should you begin when the architectural choice is still open?',
  ['Implement WebSockets immediately and change direction if deployment fails.', 'Implement polling first without assessing the alternatives.', 'Use plan mode to inspect the architecture and compare options for team review before implementation.', 'Ask direct execution to choose and implement an architecture in one step.'], 'c',
  'Plan mode supports exploration and trade-off analysis before committing to a cross-cutting implementation. The team can evaluate requirements and infrastructure implications while the decision is still inexpensive to change. Beginning with an arbitrary transport or combining selection and implementation skips that decision point.', ['workflows']);
add(17, [6], 'coding', 'coding',
  'A graph traversal feature must handle disconnected nodes, cycles, weighted edges, and performance limits. Which workflow gives Claude the strongest basis for measurable improvement over several iterations?',
  ['Supply a reference implementation and compare outputs manually after a rewrite.', 'Produce a long research and planning response before attempting one complete implementation.', 'Define tests for required behavior, edge cases, and performance, then implement and iterate from concrete test failures.', 'Give a prose specification and describe observed problems after each manual review.'], 'c',
  'Executable tests provide repeatable evidence of correctness and performance, and failures identify specific behavior to improve. Reference code and planning can support the work, but neither provides the same project-specific acceptance signal. Prose feedback is less reproducible and can miss regressions.', ['workflows', 'patterns']);
add(19, [7], 'coding', 'coding',
  'You want Redis caching with a five-minute TTL for /products, but are unfamiliar with production caching and do not know what else the design must cover. What is the best first interaction?',
  ['Request only the TTL cache and discover missing requirements after implementation.', 'Provide a specification full of TBD markers and let Claude decide them while coding.', 'Inspect the current endpoint in plan mode but postpone any discussion of caching requirements.', 'Ask Claude to interview you about invalidation, cache layers, consistency needs, and failure handling before implementing.'], 'd',
  'A requirements interview surfaces decisions that a novice requester may not know to specify. Invalidation, freshness, consistency, and failure behavior affect the design as much as the TTL. Code exploration is useful, but does not replace clarifying those goals; silently filling TBDs or waiting for defects creates avoidable rework.', ['workflows']);
add(20, [8], 'coding', 'tools',
  'The team needs a shared venue-search MCP server, while you alone are trying an experimental playlist server. Which configuration correctly separates shared project access from personal configuration?',
  ['Put both servers only in your personal ~/.claude.json.', 'Commit the venue server in the project .mcp.json and keep the playlist server in your ~/.claude.json.', 'Commit both servers in the project .mcp.json.', 'Keep the venue server personal and commit the playlist server to the project.'], 'b',
  'Project-scoped MCP definitions in .mcp.json can be versioned and shared with the team. Local or user-scoped definitions in ~/.claude.json remain personal. Putting both in either location fails one of the sharing requirements. Keep credentials out of committed configuration and use the documented environment-variable mechanism where needed.', ['mcp']);
add(21, [9], 'coding', 'coding',
  'An authentication dependency upgrade changes callbacks to Promises, restructures User fields, and removes three methods. Forty-five files across multiple modules import the library. How should Claude Code approach the migration?',
  ['Paste the change list and immediately rewrite every affected file.', 'Explore usages and affected paths in plan mode, then propose a coordinated migration strategy.', 'Apply a reusable transformation command to each file before investigating its context.', 'Upgrade the package first and fix only failures that the existing tests reveal.'], 'b',
  'The changes affect asynchronous control flow, data shapes, and removed APIs across module boundaries. Mapping usages before implementation identifies dependencies and enables a coherent migration and validation plan. Blind transformations or test-failure-only fixes can miss untested paths and interactions.', ['workflows']);
add(22, [10], 'coding', 'coding',
  'A one-time payment integration must follow transaction, error, and audit patterns already demonstrated in db_utils.py, error_handlers.py, and audit_logger.py. The conventions are documented elsewhere and need no new permanent instructions. What gives Claude the most useful task context?',
  ['Paraphrase all three modules from memory in the prompt.', 'Copy all their conventions into the root CLAUDE.md.', 'Reference the three known files directly with @ mentions in the task prompt.', 'Ask Claude to search the whole repository for examples you have already located.'], 'c',
  'Direct references provide the exact implementations Claude should follow without adding permanent context for a one-off task. Paraphrasing can omit details, broad discovery repeats completed work, and expanding CLAUDE.md adds ongoing context cost for information not needed across tasks.', ['workflows', 'memory']);
add(23, [11], 'coding', 'coding',
  'Terraform, Kubernetes, and CI/CD conventions occupy a root CLAUDE.md exceeding 500 lines. You want guidance to load selectively for matching file paths and types. Which organization best supports that requirement?',
  ['Move conventions into .claude/rules files with YAML paths patterns for the relevant files.', 'Import every specialist document unconditionally from the root CLAUDE.md.', 'Keep the full root document and add clearer headings.', 'Use directory CLAUDE.md files as the only mechanism, without path patterns for file types.'], 'a',
  'Path-scoped .claude/rules entries condition guidance on matching files, allowing both directory and file-pattern targeting. Root imports and headings still load broad context. Nested CLAUDE.md files are useful for directory-level guidance, but explicit paths rules are the best match for selective file-type loading and cross-directory patterns.', ['memory']);
add(24, [12], 'coding', 'coding',
  'A generated PDF report truncates table cells, formats dates poorly, and breaks pages incorrectly. Column width affects date wrapping, and both influence page height. What iteration strategy best controls these interacting problems?',
  ['Provide only a polished example and ask for visual similarity.', 'Discard the working implementation and start over.', 'Correct and verify column widths, then date formatting, then pagination, checking the rendered output after each step.', 'Request all three changes at once and review only the final result.'], 'c',
  'Working in dependency order makes each change measurable and reduces uncertainty about which modification caused a regression. Width and date layout affect the content height used for pagination. Examples can clarify the target, but sequential fixes with rendered verification provide better diagnostic control than a broad rewrite.', ['workflows']);
add(25, [13], 'coding', 'coding',
  'Developers repeatedly paste an eight-point pull-request checklist, while other Claude sessions cover features, debugging, and documentation. How can the team make the review procedure easy to invoke only when needed?',
  ['Make plan mode the default for every review.', 'Package the checklist in a shared /review command or skill.', 'Load the entire checklist into every session through CLAUDE.md.', 'Require a dedicated review subagent even when delegation or isolated context is unnecessary.'], 'b',
  'A reusable /review command loads the checklist on demand and keeps a single shared procedure. CLAUDE.md is better suited to persistent project guidance; plan mode does not encode the checklist. A subagent can be useful for independent review, but adds a delegation mechanism beyond the stated need for an invoked checklist.', ['skills']);
add(26, [14], 'coding', 'coding',
  'A generated migration mishandles records whose required fields contain null. What feedback most effectively drives a targeted correction?',
  ['Provide a minimal failing record and its expected result, then ask Claude to fix that case and verify it.', 'Describe nulls generally and request a complete rewrite.', 'Ask Claude to think harder about edge cases without supplying evidence.', 'Patch the bug manually and move to unrelated tasks without capturing a regression case.'], 'a',
  'Concrete input and expected output turn a vague defect into a reproducible acceptance condition. They help localize the fix and support a regression test. Broad rewrites and stronger wording provide less diagnostic information, while an undocumented manual patch does not guide later iterations.', ['workflows']);
add(27, [15, 55], 'coding', 'tools',
  'An MCP server publishes deploy_checklist and incident_response prompts as well as tools. How can a user invoke those server prompts in Claude Code?',
  ['Use their MCP prompt commands, such as /mcp__servername__deploy_checklist, with supported arguments.', 'Mention them as file-like @ resources instead of commands.', 'Expect every prompt to be inserted into the system context automatically.', 'Expect the model to call prompts automatically as if they were tools.'], 'a',
  'MCP prompts are user-invoked prompt commands; Claude Code exposes their command names and supported arguments. Resources, tools, and prompts have different interaction models. Prompts are not automatically prepended to every conversation or registered as model-selected executable tools. Current UI command naming can also show a server-prefixed form; use the names listed by the connected client.', ['mcp']);
add(28, [16], 'coding', 'coding',
  'Project instructions say to protect db/migrations from edits, prefer a custom logger, and format TypeScript after each edit. Claude nevertheless edits a migration. Which combination best assigns each requirement to the right mechanism?',
  ['Use permission deny rules for protected edits, retain the logger preference in CLAUDE.md, and run Prettier from a PostToolUse formatting hook.', 'Use stronger prose and more examples for all three requirements in CLAUDE.md.', 'Use hooks for everything, including injecting the logger preference before each edit.', 'Express every requirement only as a path-scoped instruction file.'], 'a',
  'Permissions enforce denied tool operations, project instructions convey a coding preference, and a post-edit hook performs formatting deterministically. Prose alone is not an enforcement mechanism. Cover Edit and Write and any other permitted write path when protecting migrations: an Edit-only deny rule is not a filesystem-wide guarantee, and stronger isolation may be needed if shell writes remain available.', ['permissions', 'hooks', 'memory']);
add(29, [17, 18], 'coding', 'coding',
  'Emphasizing Prettier rules in CLAUDE.md reduces formatting violations from 30% to 15% but does not eliminate them. Which mechanism most directly applies formatting to every supported file Claude changes?',
  ['Create a longer formatting skill with more examples.', 'Ask a prompt-based Stop hook to judge formatting at session end.', 'Run Prettier automatically in a PostToolUse hook matching Edit and Write.', 'Move the same prose into path-scoped rules.'], 'c',
  'A PostToolUse command hook can run the formatter after successful edits and writes, applying the configured indentation and punctuation rules rather than relying on recall. Scope it to supported files and account for other write mechanisms in the workflow. Prose and model-based checks can still be skipped or mistaken; they do not perform the formatter operation themselves.', ['hooks']);
add(30, [19], 'coding', 'coding',
  'The whole team should invoke /migrate-component for an evolving React-to-Vue workflow. Where should its shared skill definition live?',
  ['Only in ~/.claude/skills/migrate-component/SKILL.md on individual machines.', 'In .claude/skills/migrate-component/SKILL.md in the project, committed to version control.', 'Inline in a settings.json skillOverrides entry instead of a skill file.', 'As a long section of the root CLAUDE.md without an invocable skill.'], 'b',
  'A project skill at .claude/skills/migrate-component/SKILL.md is shared through version control and exposes the workflow under its skill name. Personal skills are not automatically distributed. skillOverrides configures existing skills rather than serving as the workflow body, and CLAUDE.md does not by itself create that command.', ['skills']);

add(31, [20], 'developer', 'architecture',
  'Yesterday an agent analyzed a legacy authentication module and identified two options: extract a microservice or refactor in place. An engineer now wants independent, detailed implementation proposals for both, reusing the analysis. How should you organize the sessions?',
  ['Resume for one option but reconstruct the other in a new empty session.', 'Explore both alternatives consecutively in one conversation.', 'Start two empty sessions and manually repeat the original investigation.', 'Resume the analysis into two forks using fork_session, developing one alternative in each branch.'], 'd',
  'Forking from the same saved session preserves the shared investigation while keeping subsequent reasoning about each option separate. Sequential work mixes alternatives in one history; fresh sessions require context reconstruction. Session forks separate conversation histories, not working directories, so isolate filesystem changes too if either branch begins editing.', ['sessions']);
add(32, [21], 'developer', 'architecture',
  'An engineer requests comprehensive tests for a 200-file legacy project without setting priorities. Which decomposition strategy best starts useful work and adapts as the code becomes clearer?',
  ['Allocate identical effort to each directory according to a fixed upfront schedule.', 'Inventory every function in all 200 files before writing any tests.', 'Map the repository with Glob and Grep, prioritize high-impact coupled modules, and revise the plan as dependencies emerge.', 'Test files alphabetically and rely on incidental discoveries to determine what matters.'], 'c',
  'An initial structural map supports risk- and impact-based priorities without requiring exhaustive reading before any value is delivered. Updating the plan as dependencies are discovered suits an open-ended task. Equal allocation, alphabetical order, and a complete upfront inventory ignore business risk or spend effort before priorities are understood.', ['patterns', 'workflows']);
add(33, [22], 'developer', 'tools',
  'Before deleting calculateTax, the agent must find its callers. Wrapper modules expose the same function under aliases such as computeOrderTax. Which search strategy best handles those aliases?',
  ['Inspect the definition and wrappers to discover exported names, then search the repository for each name and follow further aliases.', 'Search imports from only the original library and inspect those files.', 'Search only the original identifier calculateTax.', 'Use documentation as the sole map of integration points.'], 'a',
  'Following wrappers and aliases expands the search beyond the original symbol, allowing renamed call sites to be found. Original-name searches miss wrapper callers, and documentation can be incomplete. For full confidence, also inspect re-exports, dynamic usages, and language-aware references where available; text search alone does not mathematically prove that no caller remains.', ['workflows']);
add(34, [23], 'developer', 'architecture',
  'A saved investigation contains an hour of authentication analysis. Since then, a teammate changed three of the twelve files already examined. How should the agent continue efficiently with current evidence?',
  ['Resume the session and identify the changed files for focused re-reading and dependency checks.', 'Resume without mentioning the changes.', 'Discard the investigation and start from an empty session.', 'Re-read every previously inspected file whether changed or not.'], 'a',
  'Resumption retains useful architectural context, while targeted re-analysis refreshes the evidence that actually changed. Follow any affected dependencies if necessary. Ignoring the changes risks obsolete conclusions; restarting or re-reading everything throws away valid work without a demonstrated need.', ['sessions', 'workflows']);
add(35, [24], 'developer', 'architecture',
  'Every pull-request review uses the same fixed stages: style analysis, security analysis, and documentation analysis, followed by a combined report. Which of the listed patterns best matches this predefined staged workflow?',
  ['An orchestrator that invents a new set of worker tasks for every pull request.', 'Prompt chaining with a separate analysis step for each aspect and a final synthesis.', 'One large prompt that performs all aspects in a single response.', 'Routing by pull-request category instead of carrying out the three required checks.'], 'b',
  'Prompt chaining fits a known sequence of focused subtasks followed by synthesis. A dynamic orchestrator is more useful when subtasks cannot be specified in advance; routing selects a path rather than ensuring all three checks occur. If these checks are independent and latency matters, parallel sectioning is also a valid architecture, but it is not one of the listed choices for the stated staged workflow.', ['patterns']);
add(36, [25], 'developer', 'tools',
  'A healthy MCP code-analysis server lists analyze_dependencies, but its description only says "Analyzes dependency graph". The agent repeatedly uses Grep instead, whose description is much more specific. What should you improve first?',
  ['Add a global routing instruction for every dependency-related request.', 'Split the operation into more tools before clarifying its capabilities.', 'Remove Grep whenever the MCP server is connected.', 'Describe the analysis tool clearly, including direct and transitive dependencies, cycles, inputs, and returned output.'], 'd',
  'A specific tool description explains why graph analysis differs from text search and when it should be selected. Descriptions are part of the agent-facing interface. Removing a useful general tool or adding more ambiguous tools treats the symptom, while global routing instructions are less maintainable than fixing the tool definition itself.', ['tools', 'patterns']);
add(37, [26, 56], 'developer', 'context',
  'Caching code spans fifteen files and about 8,000 lines across decorators, middleware, and services. Before adding an invalidation trigger, what is the best next step for understanding the design within limited context?',
  ['Load all fifteen files in full immediately.', 'Find the base cache abstraction through imports and class relationships, read its interface, then trace the relevant invalidation paths.', 'Read the largest cache-related files first because size indicates architectural importance.', 'Read only isolated matches for invalidate or expire with almost no surrounding code.'], 'b',
  'Starting from the shared abstraction establishes the cache contract and helps select relevant implementations and call paths. It supplies the context needed to interpret invalidation behavior without loading every line. File size is not a reliable priority signal, and tiny keyword snippets can hide lifecycle assumptions and side effects.', ['workflows']);
add(38, [27], 'developer', 'tools',
  'The agent connects to Git, Jira, and documentation MCP servers. A user asks it to create a branch for JIRA-123 and attach relevant documentation links to the ticket. How can it perform this cross-server task?',
  ['The application must select exactly one server per turn.', 'Only one server can be connected, selected by request relevance.', 'Tools from multiple configured servers can be discovered and used within the same agent session.', 'Every tool call must first probe each server to locate the tool by trial and error.'], 'c',
  'An MCP client can connect multiple servers and expose their tools in one session, allowing the model to combine Git, search, and Jira operations. Namespaced tool identifiers route calls to the correct server. Some clients defer loading definitions until needed, but this does not impose a one-server-per-turn restriction or require probing every server for each call.', ['mcp']);
add(39, [28], 'developer', 'architecture',
  'An exploration subagent has read 47 payment-system files when its session is interrupted. During the interruption, a teammate renames two utility functions. What is the best way to continue that investigation?',
  ['Resume the saved exploration but ignore the renames.', 'Resume the supported saved subagent/session transcript and supply the renamed functions for targeted refresh.', 'Start a new agent and paste the entire prior transcript manually.', 'Start a new agent with only a short summary even though the saved investigation is resumable.'], 'b',
  'Resuming the saved investigation preserves detailed findings and supplying the renames identifies the evidence that needs refreshing. A fresh agent loses or reconstructs useful context, and ignoring repository changes can lead to invalid symbol references. Use the resumption mechanism supported by the SDK version rather than assuming every subagent API has the same parameters.', ['sessions', 'subagents']);
add(40, [29], 'developer', 'architecture',
  'After analyzing 23 service files, the agent must independently compare end-to-end tests with mocked services against snapshot-based tests. How should it reuse the investigation while keeping each proposal separate?',
  ['Fork the saved analysis session for each testing strategy.', 'Develop both strategies consecutively in the original history.', 'Make two fresh agents repeat all source exploration.', 'Export a brief summary and discard the available saved context.'], 'a',
  'Session forks share the same starting investigation and then diverge, preserving context without mixing the two proposals. Repeating exploration costs time, and a brief export can omit important details. If the branches modify code, provide separate working trees because conversation branching alone does not isolate filesystem changes.', ['sessions']);
add(41, [30], 'developer', 'context',
  'After extensive rendering-engine analysis, the agent starts referring to generic rendering patterns instead of the VulkanPipeline and FrameGraph classes it found. It now needs to investigate physics integration for collision overlays. What is the best next step?',
  ['Capture the concrete rendering findings and pass that focused summary to a physics exploration subagent.', 'Keep extending the same crowded history with reminders of class names.', 'Ask a new physics agent to work without the rendering findings, then reconstruct the relationship manually.', 'Clear everything and rely only on general project paths.'], 'a',
  'A focused handoff preserves the concrete interfaces relevant to the integration while giving the new investigation a clean working context. The summary should include source paths, discovered contracts, and open questions. Continuing an overloaded context or starting without the rendering facts increases the risk of generic or disconnected conclusions.', ['subagents', 'workflows']);
add(42, [31], 'developer', 'context',
  'The agent is investigating untested paths across 45 payment files. After reading eight files it is losing previously found patterns and has not located all tests or traced key payment flows. Which approach best completes the investigation?',
  ['Delegate bounded investigations, such as finding payment tests and tracing refund dependencies, while the main agent integrates concise findings.', 'Clear the context and use a single summary as the only source of further evidence.', 'Use only function-name searches for the rest of the task.', 'Repeatedly clear the context and re-read a small subset of files without dividing the investigation.'], 'a',
  'Bounded subagent tasks isolate detailed exploration and return focused evidence to a coordinating agent, reducing context pressure while covering the missing work. Keep source references and uncertainties in each report. Summaries and targeted searches are helpful tools, but neither alone replaces tracing the distinct flows and test inventory.', ['subagents', 'patterns']);
add(43, [32], 'developer', 'architecture',
  'An intermittently failing endpoint may involve routing, middleware, business logic, or database access in a 200-file project. The relevant path is not yet known. Which investigation plan best fits this uncertainty?',
  ['Assign every layer an identical parallel investigation before collecting any evidence.', 'Create and revise subtasks as logs, code, and dependencies reveal the actual error path.', 'Map every possible path completely before reading any file.', 'Follow a rigid search sequence regardless of intermediate results.'], 'b',
  'An adaptive investigation follows evidence to refine hypotheses and select the next relevant subtask. This fits an open-ended failure whose cause and dependency graph are initially unknown. Fixed plans can waste effort on unrelated layers; parallel work can help once concrete independent questions have been identified.', ['patterns']);
add(44, [33], 'developer', 'architecture',
  'Compare two tasks: rename getUserData to fetchUserProfile everywhere, and redesign error handling across a data-processing module to prevent silent corruption. Which benefits most from an explicit analyze, propose, implement, and review workflow?',
  ['The error-handling redesign.', 'Both benefit equally, regardless of complexity.', 'Neither task gains meaningful benefit.', 'The mechanical function rename.'], 'a',
  'Error handling involves behavioral decisions, recovery boundaries, data integrity, and interactions across paths, so staged analysis and review reduce design risk. A rename still needs reference checks and validation, but usually has a much more constrained transformation and gains less from a heavy multi-phase process.', ['patterns', 'workflows']);
add(45, [34], 'developer', 'coding',
  'An engineer wants to continue yesterday\'s named auth-deep-dive investigation after working in several other repositories and sessions. Which Claude Code option selects that particular saved conversation?',
  ['Use --session-id with an arbitrary existing transcript UUID.', 'Start over and repeat the investigation.', 'Use --continue, which always selects the desired named session.', 'Use --resume auth-deep-dive.'], 'd',
  '--resume accepts a session name or identifier to select an existing conversation. --continue targets the most recent relevant conversation rather than a specific older name, and --session-id is not the selector for resuming an existing transcript. Explicit selection preserves the intended investigation without repeating it.', ['cli', 'sessions']);

add(46, [35], 'support', 'tools',
  'lookup_order returns the same generic failure for an unknown order, a network interruption, and a permission problem. The agent responds with inconsistent retries, clarification requests, or escalation. What tool change best enables appropriate recovery?',
  ['Return an error category, a retryability flag, and a useful cause and recovery description.', 'Add examples teaching the agent to infer categories from the identical generic message.', 'Retry every error internally until a common retry limit is exhausted.', 'Require another tool call merely to classify every failed lookup.'], 'a',
  'Structured categories and retryability expose the distinctions needed to choose retry, corrected input, alternative lookup, or escalation. Preserve an appropriate error flag as well as actionable content. Identical messages do not contain enough information for examples to recover, indiscriminate retries waste resources, and a separate classifier adds an avoidable dependency.', ['tools', 'results']);
add(48, [36, 57], 'support', 'tools',
  'After adding delivery tools, tool-selection accuracy falls from 88% to 71%. Most errors confuse issue_credit with process_refund or call check_delivery_status when lookup_order already provides that data. Which option directly removes these overlapping tool choices?',
  ['Merge compensation into resolve_compensation with an explicit action parameter, and expose tracking through an include_tracking option on lookup_order.', 'Divide the same overlapping tools across two specialists without changing their interfaces.', 'Keep every interface and add more selection examples.', 'Defer loading the new tools but retain their overlapping responsibilities.'], 'a',
  'Consolidating the identified overlaps removes competing top-level tools and makes the intended operation an explicit validated argument. Preserve action-specific authorization and input validation so refunds and credits remain distinct operations. Examples, routing, and deferred loading may help selection, but leave the interface overlap itself in place.', ['tools', 'patterns']);
add(49, [37], 'support', 'architecture',
  'Complex disputes sometimes hit max_turns after information gathering but before resolution or handoff. The service must ensure that every terminated interaction has either a recorded resolution or a human escalation, regardless of the termination reason. What design provides that control?',
  ['Check terminal outcomes in orchestration code and trigger a verified handoff with accumulated context whenever no resolution or escalation exists.', 'Separate gathering and resolution into two agents and assume independent budgets prevent all premature exits.', 'Ask the model to remember to escalate when it estimates that its remaining budget is low.', 'Count tool calls and terminate at 80% of max_turns, assuming that covers every possible exit.'], 'a',
  'An application-level terminal check runs independently of whether the model stopped normally, exhausted its budget, or failed unexpectedly. It can initiate an idempotent handoff, persist it, retry delivery failures, and verify receipt. A prompt or an early tool-count threshold cannot cover every termination path; simply splitting agents also leaves failure paths. External handoff failures still need durable recovery rather than a false success claim.', ['patterns', 'hooks']);
add(50, [38], 'support', 'architecture',
  'Refunds above $500 require a human approval path. Prompt instructions still allow occasional direct refunds. Which option enforces both blocking the action and initiating the required escalation?',
  ['Add stronger capitalization and prohibitions to the prompt.', 'Have the refund tool reject large amounts and leave escalation entirely to the model.', 'Add examples for refunds at $400, $500, and $600.', 'Intercept the refund call in a deterministic pre-execution hook, block amounts above $500, and invoke the human handoff.'], 'd',
  'A pre-execution policy gate can prevent the disallowed refund and initiate escalation without relying on model discretion. The rule is above $500, so exactly $500 does not cross this stated threshold. Tool rejection alone blocks a refund but does not guarantee handoff. Also enforce monetary limits and authorization in the backend to cover other callers, with durable escalation and receipt checking.', ['hooks', 'permissions']);
add(51, [39], 'support', 'context',
  'The agent has verified a customer and established refund eligibility, but process_refund times out. What response best preserves useful first-contact assistance without claiming an uncompleted action?',
  ['Transfer immediately without explaining any verified information.', 'Explain the charges and eligibility, disclose that processing could not be confirmed, and offer an appropriate handoff or later retry.', 'Tell the customer the refund is complete because eligibility is known.', 'Retry indefinitely while keeping the conversation open until a refund eventually succeeds.'], 'b',
  'The agent can communicate verified findings while accurately distinguishing eligibility from a completed transaction. A timeout may leave the backend outcome uncertain, so check transaction status and use idempotency before any bounded retry. Offer escalation or an agreed next step rather than promising success, retrying indefinitely, or discarding the assistance already provided.', ['patterns', 'results']);
add(52, [40], 'support', 'architecture',
  'lookup_order reports a purchase made 45 days ago. In a model-directed agentic loop, how is the next action—such as refunding or escalating—normally selected?',
  ['The infrastructure always maps the status field directly to the next tool.', 'The agent necessarily follows a fixed decision tree configured before the conversation.', 'The tool result enters the conversation, and the model chooses the next action using that evidence and the applicable instructions.', 'All remaining actions were irrevocably planned before the first lookup.'], 'c',
  'In an agentic loop, the model receives tool results and updates its action choice from the current evidence. A deterministic workflow can instead use fixed routing, but that is a different orchestration choice. The age alone does not establish refund eligibility without the policy, and application authorization gates must still constrain any model-selected action.', ['patterns', 'tools']);
add(53, [41], 'support', 'tools',
  'process_refund can fail transiently with a 503 or timeout, or permanently because a return window expired or a refund already exists. The agent wastes several turns retrying permanent business failures. What most directly improves its recovery decisions and customer explanation?',
  ['Retry technical errors inside the tool but leave business errors as unstructured text.', 'Return structured business failures with retriable: false and an understandable explanation, distinguishing them from transient failures.', 'Teach the agent to infer retryability only by matching message wording.', 'Add an eligibility tool and assume no business-rule failure can occur afterward.'], 'b',
  'Explicit retryability and business context tell the agent why another identical request cannot succeed and what to explain to the customer. Internal transient retries can complement this design, but do not replace an actionable business response. Message parsing is brittle, and an eligibility precheck cannot eliminate races or already-completed actions.', ['tools', 'results']);
add(54, [42], 'support', 'context',
  'After retrieving customer and order data, the agent discovers a promotional-pricing dispute requiring manager approval. Which handoff best allows a human to continue without repeating the investigation?',
  ['Send only the customer\'s initial message.', 'Send only a database history identifier and no concise case summary.', 'Attempt an unauthorized refund first and transfer only if it is rejected.', 'Prepare a structured summary with customer and order context, verified findings, attempted actions, and the approval needed, then escalate.'], 'd',
  'A structured handoff gives the human the actionable state and reason for escalation, reducing repeated questions and preserving verified findings. Attach a transcript or reference for supporting detail where appropriate, with only necessary customer data. A raw history pointer alone may obscure the unresolved issue, and authority limits must not be tested by attempting an unauthorized transaction.', ['patterns']);
add(55, [43], 'support', 'context',
  'Which escalation criteria best reflect a real need for human involvement in a support case?',
  ['Escalate after exactly three tool calls even if useful progress continues.', 'Escalate whenever punctuation or negative wording raises a sentiment score.', 'Use only a static mapping of issue category and customer segment for every decision.', 'Escalate when the customer asks for a person, a policy exception is required, or meaningful progress is no longer possible.'], 'd',
  'These criteria connect escalation to user preference, authorization limits, and inability to resolve the case. A fixed call count can interrupt progress, sentiment is an imperfect proxy for need, and static categories alone cannot capture every case. Mandatory business rules should still be enforced deterministically alongside these contextual criteria.', ['patterns']);
add(56, [44], 'support', 'tools',
  'When a customer requests a refund without an order identifier, Claude invents order_id and calls process_refund before lookup_order. Which tool-interface change most directly teaches the missing prerequisite?',
  ['Force some tool call on every turn using any-tool selection.', 'Extract only order identifiers already present in customer messages.', 'State in process_refund\'s description that order_id must come from a verified prior lookup_order result and must never be guessed.', 'Validate database existence only after the agent has already supplied an identifier.'], 'c',
  'The description makes the dependency and source of order_id explicit at the point of tool selection. Any-tool forcing does not choose the prerequisite, and message parsing cannot recover an ID the user did not give. Backend validation remains essential but alone does not explain how to obtain the correct value; bind refunds to an authorized verified order as an enforcement safeguard.', ['tools']);
add(57, [45], 'support', 'context',
  'During a multi-step identity check, the agent asks for the customer\'s name again after receiving the third verification answer. Which integration defect most plausibly explains the lost conversational context?',
  ['The prompt does not command the model to remember every message.', 'Claude retains only two turns unless a memory-length setting is increased.', 'Later API calls omit the preceding conversation or fail to resume the saved session.', 'Every verification tool automatically clears model state on success.'], 'c',
  'The API needs the relevant conversation history, or a correctly resumed SDK session, to retain earlier exchanges. There is no universal two-turn memory default, and tools do not inherently erase a conversation. Inspect message assembly and session handling before trying stronger reminder instructions.', ['sessions', 'tools']);
add(58, [46], 'support', 'context',
  'A customer returns four hours after a 32-turn dispute conversation. Old tool results said the refund was pending, and the resumed agent keeps repeating that status even after fresh data differs. Which approach best avoids anchoring on obsolete operational results?',
  ['Delete every earlier tool-result message but keep all assistant claims from the old conversation.', 'Keep the entire history and rely only on an instruction to prefer newer results.', 'Begin with a concise structured case summary and obtain fresh backend state before stating the current status.', 'Replay every previously used tool automatically, regardless of whether it changes state.'], 'c',
  'A focused case summary preserves the issue and prior actions without flooding the new interaction with obsolete tool data. Fresh read-only lookups establish the present status. Removing results alone can leave stale assistant assertions, and blindly replaying tools risks repeating refunds or other side effects. Historical resolution status should be labeled as historical until verified.', ['sessions', 'workflows']);
add(59, [47], 'support', 'context',
  'A long conversation covers a refund, a subscription, and a payment-method change. Near the context limit, the customer asks again about the refund discussed much earlier. Which strategy best preserves the details of all open issues?',
  ['Use only a prose recap of old turns and keep full detail solely for the current topic.', 'Retain just the most recent thirty turns.', 'Persist a structured per-issue state containing identifiers, amounts, verified actions, status, and unresolved next steps.', 'Discard earlier state and assume backend tools can reconstruct every conversational fact later.'], 'c',
  'Structured per-issue state preserves the precise facts needed to resume any topic even after the original turns leave the working context. Include provenance and timestamps so mutable statuses can be refreshed. A sliding window can drop the refund entirely, prose summaries can lose identifiers, and backend tools cannot necessarily recover promises, user preferences, or unresolved conversation decisions.', ['workflows', 'sessions']);
add(60, [58], 'support', 'tools',
  'lookup_order flags every exception as an error but returns only "Tool execution failed". The agent either repeats the same call or escalates without trying alternatives. Which response design best supplies the information needed for recovery?',
  ['Insert a separate classifier in front of the agent while keeping the original tool response generic.', 'Remove the error flag so failures look like successful data.', 'Retry every operation internally and provide no error-specific recovery guidance.', 'Keep the error flag and return cause-specific instructions, such as an alternative lookup for a missing order or a bounded retry suggestion for a transient timeout.'], 'd',
  'Actionable error results tell the model what failed and which recovery is appropriate while preserving the distinction between success and failure. A missing order may need a different lookup, while a transient read timeout may justify retry. Suppressing the error flag misrepresents the outcome; blanket retries cannot fix permanent errors. For side-effecting operations, verify outcome and idempotency before retrying.', ['results', 'tools']);

